#include <stdio.h>


int main(void)
{
    int a[] = {-4, -2, -2};
    int best = a[0];
    for (int i = 1; i < 3; i++) {
        if (a[i] > best) {
            best = a[i];
        }
    }
    printf("%d\n", best);
    return 0;
}

